import{_ as t,o as s,c as e,a2 as i}from"./chunks/framework.ORnkkB96.js";const k=JSON.parse('{"title":"Instalação","description":"","frontmatter":{},"headers":[],"relativePath":"pt/instalacao.md","filePath":"pt/instalacao.md","lastUpdated":1792519643000}'),o={name:"pt/instalacao.md"};function r(n,a,d,l,h,p){return s(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="instalacao" tabindex="-1">Instalação <a class="header-anchor" href="#instalacao" aria-label="Permalink to &quot;Instalação&quot;">​</a></h1><p>O Vision.AI roda containerizado com <strong>Docker Swarm</strong>. O instalador oficial baixa a versão correta, descompacta e sobe os quinze serviços de uma vez.</p><blockquote><p>O guia completo, por sistema operacional, está no repositório do instalador: <strong><a href="https://github.com/bortolottic/vision.ai.installer" target="_blank" rel="noreferrer">vision.ai.installer</a></strong>. Esta página é o resumo.</p></blockquote><h2 id="requisitos" tabindex="-1">Requisitos <a class="header-anchor" href="#requisitos" aria-label="Permalink to &quot;Requisitos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Recurso</th><th>Mínimo</th><th>Recomendado</th></tr></thead><tbody><tr><td>Memória RAM</td><td>8 GB</td><td>16 GB</td></tr><tr><td>Processador</td><td>4 núcleos</td><td>8 núcleos</td></tr><tr><td>Disco</td><td>40 GB livres</td><td>100 GB livres</td></tr></tbody></table><p>A inferência e o treino rodam em <strong>CPU</strong> por padrão. Para tempo real com várias câmeras, use um nó com <strong>GPU NVIDIA</strong> e o modo <code>--gpu</code> (ver <a href="/vision.ai.installer/pt/operacao#gpu">Operação</a>).</p><h2 id="portas" tabindex="-1">Portas <a class="header-anchor" href="#portas" aria-label="Permalink to &quot;Portas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Porta</th><th>Para que serve</th></tr></thead><tbody><tr><td><strong>9080</strong></td><td>A plataforma no navegador</td></tr><tr><td>8189/UDP</td><td>WebRTC (vídeo ao vivo)</td></tr><tr><td>3433</td><td>Banco (só inspeção; pode ser fechado)</td></tr><tr><td>443</td><td>HTTPS, no modo <code>--ssl</code></td></tr></tbody></table><h2 id="passos" tabindex="-1">Passos <a class="header-anchor" href="#passos" aria-label="Permalink to &quot;Passos&quot;">​</a></h2><ol><li>Instale o Docker e ative o Swarm:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swarm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div></li><li>Rode o instalador:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/bortolottic/vision.ai.installer/refs/heads/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div></li><li>Acesse <code>http://localhost:9080</code> (ou o endereço do servidor na porta 9080).</li></ol><p>Para uma versão específica, acrescente a tag:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/bortolottic/vision.ai.installer/refs/heads/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> V1.0.0.0</span></span></code></pre></div><h2 id="depois-de-instalar" tabindex="-1">Depois de instalar <a class="header-anchor" href="#depois-de-instalar" aria-label="Permalink to &quot;Depois de instalar&quot;">​</a></h2><ul><li><strong>Segredos:</strong> gerados automaticamente na primeira instalação e gravados em <code>/tmp/vision-ai/vision-ai/.env.production</code>. <strong>Faça backup desse arquivo.</strong></li><li><strong>Endereço público:</strong> em servidor, ajuste <code>VISION_PUBLIC_URL</code> e <code>VISION_WEBRTC_HOST</code> no <code>.env.production</code> e rode <code>./deploy_production.sh</code> de novo.</li></ul><p>Detalhes de GPU, HTTPS e backup estão em <a href="/vision.ai.installer/pt/operacao">Operação</a>.</p>',15)])])}const u=t(o,[["render",r]]);export{k as __pageData,u as default};
